<script>
/* ---------- 小工具 ---------- */
const firstVal = x => Array.isArray(x) ? (x.length ? x[0] : '') : x;
function get(obj, path, fallback=''){
  try{
    const ks = Array.isArray(path) ? path : String(path).split('.');
    let cur = obj;
    for (const k of ks){ if (!cur || typeof cur!=='object' || !(k in cur)) return fallback; cur = cur[k]; }
    const v = firstVal(cur); return (v==null ? fallback : v);
  }catch{ return fallback; }
}
function text(id, raw){
  const el = document.getElementById(id); if (!el) return;
  let v = firstVal(raw); if (Array.isArray(v)) v = v.join('；');
  el.textContent = (v==null || v==='') ? '—' : String(v);
}
function barWidth(el, raw, lo=0, hi=100){
  if (!el) return; const n = Number(firstVal(raw));
  el.style.width = Number.isFinite(n) ? ((Math.max(lo,Math.min(hi,n))-lo)/(hi-lo)*100)+'%' : '0%';
}

/* ---------- 角色渲染 ---------- */
function extractRoles(data){
  let root = data && data.chars;
  if (typeof root === 'string'){ try{ root = JSON.parse(root); }catch{ root=null; } }
  if (!root || typeof root!=='object' || Array.isArray(root)) return [];
  return Object.entries(root)
    .filter(([k,v]) => !k.startsWith('$') && v && typeof v==='object' && !Array.isArray(v))
    .map(([__name,__data]) => ({__name,__data}));
}
function buildRoleRibbon(data){
  const host = document.getElementById('role-ribbon');
  if (!host) return; host.innerHTML='';
  const roles = extractRoles(data);
  const fields = [
    ['年龄','年龄'], ['性别','性别'],
    ['身份','身份'], ['性格','性格'],
    ['外貌','外貌'], ['衣着','衣着'],
    ['人际关系','人际关系'], ['性经验','性经验'],
    ['特殊能力','特殊能力'], ['身体状况','身体状况'],
    ['目标','当前目标'], ['所想','当前所想']
  ];
  const toText = v => {
    let t = firstVal(v); if (Array.isArray(t)) t = t.join('；');
    return (t==null || t==='' || typeof t==='object') ? '—' : String(t);
  };
  roles.forEach(({__name,__data})=>{
    const card = document.createElement('div'); card.className='role-card';
    const meta = toText(get(__data,'当前位置','未知'));
    let lines = fields.map(([label,key])=>`<div class="role-line"><strong>${label}：</strong>${toText(get(__data,key,'—'))}</div>`).join('');
    const fav = get(__data,'好感度',0);
    card.innerHTML = `
      <div class="role-card-header">
        <div class="role-avatar">${String(__name).slice(0,1)}</div>
        <div><div class="role-name">${__name}</div><div class="role-meta">${meta}</div></div>
      </div>
      ${lines}
      <div class="role-line"><strong>好感度：</strong><span>${toText(fav)}</span>
        <div class="mini-bar"><div class="val"></div></div>
      </div>`;
    host.appendChild(card);
    barWidth(card.querySelector('.mini-bar .val'), fav, 0, 100);
  });
}

/* ---------- 异变渲染 ---------- */
function extractIncidents(data){
  let root = data && data.incidents;
  if (typeof root === 'string'){ try{ root = JSON.parse(root); }catch{ root = null; } }
  if (!root || typeof root!=='object' || Array.isArray(root)) return [];
  return Object.entries(root)
    .filter(([k,v])=>!k.startsWith('$') && v && typeof v==='object' && !Array.isArray(v))
    .map(([__name,__data])=>({__name,__data}));
}

function buildIncidentList(data){
  const host = document.getElementById('incident-list');
  if (!host) return;
  host.innerHTML = '';

  const items = extractIncidents(data);
  const toText = v => {
    let t = firstVal(v); if (Array.isArray(t)) t = t.join('；');
    return (t==null || t==='' || typeof t==='object') ? '—' : String(t);
  };

  items.forEach(({__name,__data})=>{
    const name   = toText(get(__data, '异变名称', __name));
    const status = toText(get(__data, '异变进程', '未知'));
    const fields = [
      ['影响', '异变影响'],
      ['退治者', '异变退治者'],
      ['发起者', '异变发起者'],
      ['黑幕', '异变黑幕'],
      ['其他信息', '其他异变信息']
    ];
    const card = document.createElement('div');
    card.className = 'role-card'; // 复用角色卡样式
    card.innerHTML = `
      <div class="role-card-header">
        <div class="role-avatar">异</div>
        <div>
          <div class="role-name">${name}</div>
          <div class="role-meta">进程：${status}</div>
        </div>
      </div>
      ${fields.map(([label,key])=>`<div class="role-line"><strong>${label}：</strong>${toText(get(__data, key, '—'))}</div>`).join('')}
    `;
    host.appendChild(card);
  });
}

/* ---------- 读数据 & 首次渲染 ---------- */
function readState(){
  try{
    if (typeof getVariables==='function'){
      const v = getVariables({ type:'message', message_id:(typeof getCurrentMessageId==='function'?getCurrentMessageId():undefined) });
      return (v && v.stat_data) || {};
    }
  }catch{}
  return {};
}
function renderAll(){
  const data = readState();
  // 正文补充
  text('main-extra', data['附加正文']);
  // 环境与用户
  [
    ['env-date','日期'], ['env-time','时间'], ['env-weather','世界.天气'],
    ['nearby-people','世界.附近人物'], ['nearby-places','世界.附近地点'],
    ['user-identity','user.身份'], ['user-location','user.当前位置'], ['user-events','user.重要经历'],
    ['user-name','user.姓名'], ['user-gender','user.性别'], ['user-age','user.年龄'],
    ['user-relationships','user.人际关系'], ['user-abilities','user.特殊能力'],
    ['news-content','新闻摘要']
  ].forEach(([id,path])=>text(id, get(data, path, '')));
  // 角色 & 异变
  buildRoleRibbon(data);
  buildIncidentList(data);
}

/* ---------- 选项卡 & 字号 & 箭头（只绑一次） ---------- */
document.addEventListener('DOMContentLoaded', ()=>{
  const firstDelay = 1500; // ms
  setTimeout(renderAll, firstDelay);                              // 首帧
  [60,120,240,480,960,].forEach(t=>setTimeout(renderAll, t)); // 追加 5 次重绘

  // ——以下保持不变：选项卡/字号/箭头绑定——
  const tabs = document.getElementById('status-tabs');
  const area = document.getElementById('status-tab-content-area');
  tabs.addEventListener('click', e=>{
    const btn = e.target.closest('button[data-tab]'); if (!btn) return;
    tabs.querySelectorAll('button').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    const key = btn.getAttribute('data-tab');
    area.querySelectorAll('.status-tab-content')
        .forEach(p=>p.classList.toggle('active', p.id==='content_'+key));
  });

  const content = document.getElementById('content_main'); let fs=0;
  document.getElementById('increase-font').onclick = ()=>{ fs=Math.min(fs+1,5); content.style.fontSize=(100+fs*10)+'%'; };
  document.getElementById('decrease-font').onclick = ()=>{ fs=Math.max(fs-1,-3); content.style.fontSize=(100+fs*10)+'%'; };

  const ribbon = document.getElementById('role-ribbon');
  const STEP = 320;
  document.getElementById('ribbon-left').onclick  = ()=>ribbon.scrollBy({left:-STEP,behavior:'smooth'});
  document.getElementById('ribbon-right').onclick = ()=>ribbon.scrollBy({left: STEP,behavior:'smooth'});
});
</script>
</body>
</html>

